package org.bukkit; import java.util.*; import java.io.File; import org.bukkit.entity.Player;import org.bukkit.scheduler.BukkitScheduler; public final class Bukkit { public static File worldContainer=new File("."); public static Map<String,World> worlds=new HashMap<>(); public static Map<UUID,Player> players=new HashMap<>();public static File getWorldContainer(){return worldContainer;} public static World getWorld(String name){return worlds.get(name);} public static Player getPlayer(UUID id){return players.get(id);} public static Collection<? extends Player> getOnlinePlayers(){return List.of();}public static BukkitScheduler getScheduler(){return null;} }
